package pt.qpetiscos.agenda;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.view.View;import android.widget.RemoteViews;import org.json.*;import java.util.*;
public class NotesWidget extends AppWidgetProvider{
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("widget_notes",0);}
 static int[] ids(Context c){return AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,NotesWidget.class));}
 static String filter(Context c,int id){return prefs(c).getString("filter"+id,"all");}
 static JSONArray rows(Context c){String uid=WidgetAuth.account(c);if(uid.isEmpty())return new JSONArray();try{return new JSONArray(prefs(c).getString("rows_"+uid,"[]"));}catch(Exception e){return new JSONArray();}}
 static Set<String> reads(Context c){return prefs(c).getStringSet("reads_"+WidgetAuth.account(c),Collections.emptySet());}
 static boolean task(JSONObject n){return "task".equals(n.optString("kind"));}
 static boolean visible(JSONObject n){return n!=null&&n.isNull("deleted_at")&&(!task(n)||!n.optBoolean("completed"));}
 static boolean overdue(JSONObject n){try{return task(n)&&java.time.Instant.parse(n.getString("due_at")).isBefore(java.time.Instant.now());}catch(Exception e){return false;}}
 static String get(Context c,JSONObject s,String table,String query)throws Exception{try{return WidgetAgenda.requestTable(c,s,table,"GET",query,null);}catch(WidgetAuth.HttpError e){if(e.code!=401||!WidgetAuth.configured(c))throw e;return WidgetAgenda.requestTable(c,WidgetAuth.session(c,true),table,"GET",query,null);}}
 static void sync(Context c){int[] ids=ids(c);if(ids.length==0)return;String uid=WidgetAuth.account(c),status="";try{JSONObject s=WidgetAgenda.session(c);if(!uid.equals(s.getString("uid")))return;JSONArray all=new JSONArray();for(int offset=0;;offset+=500){JSONArray page=new JSONArray(get(c,s,"internal_notes","?select=id,kind,title,content,important,pinned,completed,due_at,deleted_at,updated_at,assigned_device_id&user_id=eq."+uid+"&deleted_at=is.null&order=id&limit=500&offset="+offset));for(int i=0;i<page.length();i++)all.put(page.getJSONObject(i));if(page.length()<500)break;}Set<String> seen=new HashSet<>();for(int offset=0;;offset+=500){JSONArray page=new JSONArray(get(c,s,"internal_note_reads","?select=note_id,note_revision&user_id=eq."+uid+"&device_id=eq."+s.getString("device")+"&order=note_id,note_revision&limit=500&offset="+offset));for(int i=0;i<page.length();i++){JSONObject n=page.getJSONObject(i);seen.add(n.getString("note_id")+"|"+n.getString("note_revision"));}if(page.length()<500)break;}if(!uid.equals(WidgetAuth.account(c)))return;prefs(c).edit().putString("rows_"+uid,all.toString()).putStringSet("reads_"+uid,seen).putLong("time_"+uid,System.currentTimeMillis()).apply();}catch(Exception e){status=WidgetAgenda.issue(e);long last=prefs(c).getLong("time_"+uid,0);if(last>0)status+=" · Última: "+WidgetAgenda.formatTime(last);}if(uid.equals(WidgetAuth.account(c)))for(int id:ids)render(c,id,status);}
 static void cachedRender(Context c){for(int id:ids(c))render(c,id,WidgetAgenda.hasNetwork(c)?"A sincronizar…":"Rede indisponível");}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){WidgetAgenda.schedule(c);cachedRender(c);WidgetAgenda.refreshAll(c);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){render(c,id,"");}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)prefs(c).edit().remove("filter"+id).apply();}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);String act=i.getAction();if(act==null||!act.startsWith("qp.notes."))return;int id=i.getIntExtra("wid",-1);if(id<0)return;String event=i.getStringExtra("event");if("qp.notes.filter".equals(act)){if(Arrays.asList("all","note","task").contains(event))prefs(c).edit().putString("filter"+id,event).apply();render(c,id,"");return;}if("qp.notes.refresh".equals(act)){cachedRender(c);WidgetAgenda.requestJob(c,411,0);WidgetAgenda.refreshAll(c);}}
 static void render(Context c,int id,String status){AppWidgetManager m=AppWidgetManager.getInstance(c);int t=WidgetAgenda.theme(c,id),fg=WidgetAgenda.fg(t);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_notes);v.setInt(R.id.notes_root,"setBackgroundResource",new int[]{R.drawable.widget_bg0,R.drawable.widget_bg1,R.drawable.widget_bg2}[t]);for(int x:new int[]{R.id.notes_title,R.id.notes_status,R.id.notes_empty})v.setTextColor(x,fg);for(int x:new int[]{R.id.notes_refresh,R.id.notes_add})v.setInt(x,"setColorFilter",fg);JSONArray a=rows(c);int notes=0,tasks=0;for(int n=0;n<a.length();n++){JSONObject item=a.optJSONObject(n);if(visible(item)){if(task(item))tasks++;else notes++;}}String f=filter(c,id);int[] controls={R.id.notes_all,R.id.notes_note,R.id.notes_task};String[] filters={"all","note","task"},labels={"Todas","Notas","Tarefas"};int[] counts={notes+tasks,notes,tasks};for(int n=0;n<3;n++){boolean selected=f.equals(filters[n]);v.setTextViewText(controls[n],labels[n]+" "+counts[n]);v.setTextColor(controls[n],selected?(t==0?0xffffffff:0xff402817):fg);v.setInt(controls[n],"setBackgroundResource",selected?new int[]{R.drawable.note_filter0,R.drawable.note_filter1,R.drawable.note_filter2}[t]:WidgetAgenda.card(t));v.setOnClickPendingIntent(controls[n],WidgetAgenda.action(c,NotesWidget.class,id,"qp.notes.filter",filters[n],false));}v.setTextViewText(R.id.notes_status,status);v.setViewVisibility(R.id.notes_status,status.isEmpty()?View.GONE:View.VISIBLE);v.setTextViewText(R.id.notes_empty,"Sem "+("task".equals(f)?"tarefas pendentes":"note".equals(f)?"notas":"notas ou tarefas pendentes"));v.setOnClickPendingIntent(R.id.notes_refresh,WidgetAgenda.action(c,NotesWidget.class,id,"qp.notes.refresh","",false));v.setViewVisibility(R.id.notes_add,WidgetAgenda.readOnly(c)?View.GONE:View.VISIBLE);v.setOnClickPendingIntent(R.id.notes_add,WidgetAgenda.open(c,id,"qp=note_add"));if(android.os.Build.VERSION.SDK_INT>=31){NotesWidgetRows.Factory factory=new NotesWidgetRows.Factory(c,id);factory.onDataSetChanged();RemoteViews.RemoteCollectionItems.Builder items=new RemoteViews.RemoteCollectionItems.Builder().setHasStableIds(true).setViewTypeCount(1);for(int n=0;n<factory.getCount();n++)items.addItem(factory.getItemId(n),factory.getViewAt(n));v.setRemoteAdapter(R.id.notes_rows,items.build());}else{Intent adapter=new Intent(c,NotesWidgetRows.class).putExtra("wid",id).setData(Uri.parse("qp://notesrows/"+id));v.setRemoteAdapter(R.id.notes_rows,adapter);}v.setEmptyView(R.id.notes_rows,R.id.notes_empty);Intent click=new Intent(c,NotesWidgetClick.class).putExtra("wid",id).setData(Uri.parse("qp://notesclick/"+id));v.setPendingIntentTemplate(R.id.notes_rows,PendingIntent.getBroadcast(c,id,click,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE));m.updateAppWidget(id,v);if(android.os.Build.VERSION.SDK_INT<31)m.notifyAppWidgetViewDataChanged(id,R.id.notes_rows);}
}